        vm.assume(amount <= address(c).balance + 1 ether);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= amount + 1 ether);

        // First, deal some ETH to the contract and make a Put
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        // Then call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After Collect, the contract's balance should equal sum of all Acc balances
        // We only check for the sender since others are 0
