        address[] memory users = new address[](1);
        users[0] = sender;
        for (uint i = 0; i < users.length; i++) {
            (uint256 unlock, uint256 bal) = c.Acc(users[i]);
            totalAccBalance += bal;
        }
        assertTrue(address(c).balance == totalAccBalance);
    }
}

