pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 unlockTime, uint256 collectAmount) public {
        // Bound unlock time to avoid overflow issues
        unlockTime = bound(unlockTime, block.timestamp, type(uint256).max);
        // Bound initialBalance to a reasonable range
        initialBalance = bound(initialBalance, 0, 1 ether);
        // Bound collectAmount to a reasonable range
        collectAmount = bound(collectAmount, 0, 1 ether);

        // Fund the contract with enough ether to cover initialBalance
        vm.deal(caller, initialBalance);

        // Caller puts initialBalance into their account
        vm.prank(caller);
        (bool successPut, ) = address(c).call{value: initialBalance}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        require(successPut, "Put should succeed in reference");

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Perform Collect
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record balance after Collect
        uint256 balanceAfter = c.Acc(caller).balance;

        // Rule: If Collect succeeded, balance decreased by exactly collectAmount; otherwise unchanged
        if (successCollect) {
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

