pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        // Bound inputs to reasonable values
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        unlockTime = bound(unlockTime, 0, 1000000);
        putAmount = bound(putAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1 ether, 100 ether);

        // Deal ETH to caller
        vm.deal(caller, putAmount);

        // Caller puts funds
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + unlockTime + 1);

        // Get balance before collect
        (uint unlock, uint balanceBefore) = c.Acc(caller);

        // Call collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Read balance after
        (uint unlockAfter, uint balanceAfter) = c.Acc(caller);

        // General rule: if collect succeeded (no revert), balance should not exceed previous balance minus collected amount
        // In correct contract: balanceAfter == balanceBefore - collectAmount (when withdrawal conditions met)
        // In buggy contract: balanceAfter = balanceBefore - collectAmount - 1 which could underflow
        // If revert occurred (because of underflow), the state doesn't change
        if (success) {
            // The rule: balanceAfter <= balanceBefore (since we're subtracting)
            assertTrue(balanceAfter <= balanceBefore);
        }
    }
}

